            var cm := (col - 1 + nx) % nx; var cp := (col + 1) % nx
            var xp: Array = positions[row * nx + cp]; var xm: Array = positions[row * nx + cm]
            var zp: Array = positions[rp * nx + col]; var zm: Array = positions[rm * nx + col]
            var dxx := (float(xp[0]) - float(xm[0])) / (2.0 * dx)
            var dxz := (float(xp[2]) - float(xm[2])) / (2.0 * dx)
            var dzx := (float(zp[0]) - float(zm[0])) / (2.0 * dz)
            var dzz := (float(zp[2]) - float(zm[2])) / (2.0 * dz)
            jacobians[row * nx + col] = dxx * dzz - dxz * dzx

func _update_foam() -> void:
    var f: Dictionary = test_input.get("foam", {})
    if not bool(f.get("enabled", false)):
        for i in range(foams.size()): foams[i] = 0.0
